import unreal
print('SOURCES')
for obj in unreal.ObjectIterator(unreal.NiagaraScriptSourceBase):
    p=obj.get_path_name()
    if 'SSPR' in p: print('SOURCE=' + p + '|OUTER=' + (obj.get_outer().get_path_name() if obj.get_outer() else 'None'))
print('NODES')
for node in unreal.ObjectIterator(unreal.EdGraphNode):
    p=node.get_path_name()
    if 'SSPR_WriteOccupancy' not in p: continue
    props={}
    for key in ('node_guid','pins'):
        try: props[key]=node.get_editor_property(key)
        except Exception as exc: props[key]='ERR:' + str(exc)
    pin_summary=[]
    if not isinstance(props.get('pins'),str):
        for pin in props.get('pins') or []:
            try: pin_summary.append((str(pin.get_editor_property('pin_name')),str(pin.get_editor_property('direction'))))
            except Exception as exc: pin_summary.append(('ERR',str(exc)))
    print('NODE=' + p + '|CLASS=' + node.get_class().get_name() + '|GUID=' + str(props.get('node_guid')) + '|PINS=' + repr(pin_summary) + '|PINSRAW=' + (props.get('pins') if isinstance(props.get('pins'),str) else 'OK'))
